using Neftyanik.Portal.Web.Localization;

namespace Neftyanik.Portal.Web.Documentation;

public sealed record GuideTable(string[] Headers, string[][] Rows);
public sealed record GuideArticle(string Id, string Category, string Roles, string Title, string Introduction,
    string[] Steps, string? Note = null, GuideTable? Table = null);

public static class DocumentationContent
{
    private static string T(string ru, string uk, string en) => AppLocalizer.Get(ru, uk, en);
    public static string Category(string id) => id switch
    {
        "start" => T("Начало работы", "Початок роботи", "Getting started"),
        "daily" => T("Работа в портале", "Робота в порталі", "Everyday tasks"),
        "excel" => T("Импорт и экспорт Excel", "Імпорт та експорт Excel", "Excel import and export"),
        _ => T("Помощь и термины", "Допомога й терміни", "Help and terminology")
    };
    public static string Role(string id) => id switch
    {
        "administrator" => T("Администратору", "Адміністратору", "Administrator"),
        "accountant" => T("Бухгалтеру", "Бухгалтеру", "Accountant"),
        _ => T("Участнику", "Учаснику", "Member")
    };

